let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

it("closes for good", async () => {
  const t = await createTenant("acme");
  const other = await createTenant("other");
  await usageRepo.recomputeUsage(t.org.id);
  await usageRepo.recomputeUsage(other.org.id);
  await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.admin, dueAt: "2026-01-01T00:00:00.000Z" }));
  const ep = await webhookRepo.insertEndpoint({ orgId: t.org.id, url: "https://x.test/h", eventTypes: ["issue.created"] } as never, "s");
  const d = await webhookRepo.enqueueDelivery(t.org.id, ep.id, "issue.created", "{}");
  const outsider = await userRepo.insertUser({ email: "o@x.test", name: "o", passwordHash: "s" });
  await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "o@x.test", role: "member", expiresInDays: 14 } as never, t.userIds.owner, hashToken("tok"));

  await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "nope" } as never)).rejects.toThrow();
  expect((await orgService.listOrganizationsForUser(t.userIds.member)).length).toBe(1);

  const closed = await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "acme" } as never);
  expect(closed.archivedAt).not.toBeNull();
  const again = await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "acme" } as never).catch((e) => e);
  expect(toAppError(again).code).toBe("conflict");

  expect(await orgService.listOrganizationsForUser(t.userIds.member)).toEqual([]);
  const principal = { userId: t.userIds.member, email: "x", activeOrgId: t.org.id, expiresAt: "2999" } as never;
  expect(await sessionService.resolveActorForOrg(principal, "acme")).toBeNull();
  await expect(sessionService.switchActiveOrg(principal, { orgId: t.org.id } as never)).rejects.toThrow();
  await expect(issueService.listIssues(t.actors.member, { orgId: t.org.id, limit: 10, cursor: null } as never)).rejects.toThrow();
  await expect(invitationService.acceptInvitation(outsider.id, { token: "tok" } as never)).rejects.toThrow();

  const now = new Date(Date.now() + 30 * 86400000);
